// gate level: one bit, then four instances
module mux2_gate (input a, input b, input sel, output y);
  wire nsel, t0, t1;
  not g0 (nsel, sel);
  and g1 (t0, a, nsel);
  and g2 (t1, b, sel);
  or  g3 (y, t0, t1);
endmodule
module mux4b_gate (input [3:0] A, B, input sel, output [3:0] Y);
  mux2_gate m0 (A[0], B[0], sel, Y[0]);
  mux2_gate m1 (A[1], B[1], sel, Y[1]);
  mux2_gate m2 (A[2], B[2], sel, Y[2]);
  mux2_gate m3 (A[3], B[3], sel, Y[3]);
endmodule
// dataflow
module mux4b_df (input [3:0] A, B, input sel, output [3:0] Y);
  assign Y = sel ? B : A;
endmodule
// behavioural
module mux4b_beh (input [3:0] A, B, input sel, output reg [3:0] Y);
  always @(*)
    if (sel) Y = B;
    else     Y = A;
endmodule
